import{_ as s,o as t,c as a,a6 as i}from"./chunks/framework.QBF2cGGQ.js";const c=JSON.parse('{"title":"00 · 定位与认知","description":"","frontmatter":{},"headers":[],"relativePath":"guide/00-orientation.md","filePath":"guide/00-orientation.md","lastUpdated":1793327470000}'),n={name:"guide/00-orientation.md"};function r(l,o,p,e,u,g){return t(),a("div",null,[...o[0]||(o[0]=[i('<h1 id="_00-·-定位与认知" tabindex="-1">00 · 定位与认知 <a class="header-anchor" href="#_00-·-定位与认知" aria-label="Permalink to &quot;00 · 定位与认知&quot;">​</a></h1><blockquote><p><strong>投入权重：5%</strong> · 这一层不产出代码，但决定你后面半年会不会走错方向。 很多转岗的人直接跳到 LangChain，结果学成了调包工。</p></blockquote><h2 id="这一层要解决的问题" tabindex="-1">这一层要解决的问题 <a class="header-anchor" href="#这一层要解决的问题" aria-label="Permalink to &quot;这一层要解决的问题&quot;">​</a></h2><p>转岗最大的风险不是&quot;学不会&quot;，是&quot;学错方向&quot;。AI 应用这个领域的信息密度极低、噪声极高——大量内容是模型厂商的营销、框架作者的布道、以及三个月就过期的教程。这一层的作用是先建立判断力，让你能分辨&quot;什么是长期有效的能力&quot;和&quot;什么是今年流行明年就废的工具&quot;。</p><h2 id="角色与边界" tabindex="-1">角色与边界 <a class="header-anchor" href="#角色与边界" aria-label="Permalink to &quot;角色与边界&quot;">​</a></h2><ul><li><strong>AI 应用工程化的定义</strong> <span class="prio prio-must">必须</span> — 把概率性的模型能力封装成稳定、可交付、可运维的产品。边界止于&quot;不训练基座模型&quot;，往上包含产品形态设计。</li><li><strong>三层分工：模型层 / 推理层 / 应用层</strong> <span class="prio prio-must">必须</span> — 模型层做预训练与对齐（博士 + 千卡），推理层做部署与加速（系统工程师），应用层做产品（你）。转岗默认进第三层。</li><li><strong>与算法工程师的区别</strong> <span class="prio prio-must">必须</span> — 算法关心&quot;模型能力上限&quot;，应用关心&quot;在成本与延迟约束下，把能力转化成可用的任务完成率&quot;。</li><li><strong>与数据工程师的区别</strong> <span class="prio prio-imp">重要</span> — 数据工程做管道与数仓，AI 应用做检索、编排、评测。两者在 RAG 的数据接入处重叠。</li><li><strong>岗位画像：AI 应用工程师 / LLM 工程师</strong> <span class="prio prio-imp">重要</span> — 前者偏产品与全栈，后者偏 pipeline 与模型适配。国内 JD 常混用，看职责里&quot;是否要求发论文&quot;来区分。</li><li><strong>岗位画像：Agent 工程师 / AI 产品工程师</strong> <span class="prio prio-opt">选学</span> — Agent 工程师重点在工具设计与可靠性；AI 产品工程师重点在场景选型与人机边界。</li></ul><h2 id="心智模型" tabindex="-1">心智模型 <a class="header-anchor" href="#心智模型" aria-label="Permalink to &quot;心智模型&quot;">​</a></h2><ul><li><strong>交付物思维 &gt; 技术栈思维</strong> <span class="prio prio-must">必须</span> — 判断标准不是&quot;我会几个框架&quot;，而是&quot;我交付过几个有评测、有监控、有人用的系统&quot;。</li><li><strong>demo 与产品的分水岭是评测 + 可观测</strong> <span class="prio prio-must">必须</span> — 能跑通叫 demo，能回答&quot;这次改动是变好还是变坏&quot;才叫产品。九成人卡在这条线。</li><li><strong>概率性系统的心智模型</strong> <span class="prio prio-must">必须</span> — 传统工程是确定性的：同样输入必得同样输出。LLM 是分布采样，你必须习惯&quot;用统计指标代替断言&quot;。</li><li><strong>单步可靠性的连乘衰减</strong> <span class="prio prio-must">必须</span> — 单步 95% 正确，10 步串联只剩约 60%。这是 Agent 一切工程约束的源头，也是&quot;为什么优先用工作流&quot;的答案。</li><li><strong>能力边界意识</strong> <span class="prio prio-imp">重要</span> — 清楚模型在哪类任务上不可靠（精确算术、实时事实、长链推理、空间关系），才不会设计出必败的产品。</li><li><strong>成本即产品约束</strong> <span class="prio prio-imp">重要</span> — token 成本直接决定定价、上下文长度、能否多轮。不懂成本核算的设计都是纸上谈兵。</li><li><strong>信息半衰期</strong> <span class="prio prio-imp">重要</span> — 框架 API 半年一变，原理三五年不变。学不动的时候，回到原理。</li></ul><h2 id="你的起点-前端" tabindex="-1">你的起点（前端） <a class="header-anchor" href="#你的起点-前端" aria-label="Permalink to &quot;你的起点（前端）&quot;">​</a></h2><ul><li><strong>存量优势：流式 UI 与交互设计</strong> <span class="prio prio-must">必须</span> — 大量 AI 产品是后端工程师写的，交互烂到没法用。能把不确定输出做成可用界面的人极度稀缺，这是你真正的护城河。</li><li><strong>存量优势：状态管理与性能优化</strong> <span class="prio prio-must">必须</span> — 多轮会话状态、长列表虚拟滚动、增量渲染——这些在 AI 场景是硬需求，恰好是前端老本行。</li><li><strong>缺口一：Python 生态</strong> <span class="prio prio-must">必须</span> — 不是学语法，是熟悉数据处理（pandas）、异步（asyncio）、以及 AI 库的调用习惯。目标：能读懂并改开源实现。</li><li><strong>缺口二：数据处理与清洗</strong> <span class="prio prio-must">必须</span> — RAG 八成时间花在文档解析和清洗上，这部分最脏最没技术光环，也最能拉开差距。</li><li><strong>缺口三：评测思维</strong> <span class="prio prio-must">必须</span> — 前端习惯&quot;我看一眼没问题&quot;，AI 必须&quot;用 200 条样本证明没退化&quot;。这是最难改的习惯。</li><li><strong>缺口四：服务端与运维常识</strong> <span class="prio prio-imp">重要</span> — 容器、队列、限流、日志、成本分摊。前端容易只关注浏览器侧。</li><li><strong>缺口五：概率与统计直觉</strong> <span class="prio prio-imp">重要</span> — 分位数、置信区间、显著性。看懂 P95 延迟和 A/B 结果需要它。</li></ul><h2 id="常见误判-提前避坑" tabindex="-1">常见误判（提前避坑） <a class="header-anchor" href="#常见误判-提前避坑" aria-label="Permalink to &quot;常见误判（提前避坑）&quot;">​</a></h2><ul><li><strong>误判一：以为要学完数学</strong> — 转应用层不需要重学线代和微积分。需要的是&quot;能解释现象&quot;，不是&quot;能推导梯度&quot;。</li><li><strong>误判二：以为框架最重要</strong> — LangChain 的抽象在生产环境经常是负担。会裸调 SDK 比会框架值钱。</li><li><strong>误判三：以为 prompt 是玄学</strong> — 它有工程方法（结构化、评测驱动、版本管理），但确实没有&quot;咒语&quot;。</li><li><strong>误判四：以为 Agent 是终局</strong> — 生产环境里大量&quot;Agent&quot;实际是带 AI 节点的固定工作流，因为可预测、可测、便宜。</li><li><strong>误判五：先学微调</strong> — 这是投入产出比最低的起点。先把 RAG 和评测跑通，再谈微调。</li></ul>',12)])])}const d=s(n,[["render",r]]);export{c as __pageData,d as default};
